import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_M 32
#define TILE_N 32
#define TILE_K 16
#define THREADS_X 16
#define THREADS_Y 16
__global__ void matmul_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int N, int K, int kChunk) {
    __shared__ float As[TILE_M][TILE_K];
    __shared__ float Bs[TILE_K][TILE_N];
    int tx = threadIdx.x; // 0..15
    int ty = threadIdx.y; // 0..15
    int blockRow = blockIdx.y * TILE_M;
    int blockCol = blockIdx.x * TILE_N;
    int kStart = blockIdx.z * kChunk;
    int kEnd = kStart + kChunk;
    if (kEnd > K) kEnd = K;
    int row0 = blockRow + ty;
    int row1 = row0 + THREADS_Y;
    int col0 = blockCol + tx;
    int col1 = col0 + THREADS_X;
    int tid = ty * THREADS_X + tx;
    float sum00 = 0.0f, sum01 = 0.0f, sum10 = 0.0f, sum11 = 0.0f;
    for (int k0 = kStart; k0 < kEnd; k0 += TILE_K) {
        #pragma unroll
        for (int idx4 = tid; idx4 < (TILE_M * TILE_K) / 4; idx4 += THREADS_X * THREADS_Y) {
            int m = idx4 / (TILE_K / 4);
            int kk4 = idx4 % (TILE_K / 4);
            int globalRow = blockRow + m;
            int globalK = k0 + kk4 * 4;
            float4 val;
            if (globalRow < M && globalK + 3 < kEnd) {
                val = *reinterpret_cast<const float4*>(&A[globalRow * K + globalK]);
            } else {
                val.x = (globalRow < M && globalK + 0 < kEnd) ? A[globalRow * K + globalK + 0] : 0.0f;
                val.y = (globalRow < M && globalK + 1 < kEnd) ? A[globalRow * K + globalK + 1] : 0.0f;
                val.z = (globalRow < M && globalK + 2 < kEnd) ? A[globalRow * K + globalK + 2] : 0.0f;
                val.w = (globalRow < M && globalK + 3 < kEnd) ? A[globalRow * K + globalK + 3] : 0.0f;
            }
            As[m][kk4 * 4 + 0] = val.x;
            As[m][kk4 * 4 + 1] = val.y;
            As[m][kk4 * 4 + 2] = val.z;
            As[m][kk4 * 4 + 3] = val.w;
        }
        #pragma unroll
        for (int idx4 = tid; idx4 < (TILE_K * TILE_N) / 4; idx4 += THREADS_X * THREADS_Y) {
            int kk = idx4 / (TILE_N / 4);
            int n4 = idx4 % (TILE_N / 4);
            int globalK = k0 + kk;
            int globalCol = blockCol + n4 * 4;
            float4 val;
            if (globalK < kEnd && globalCol + 3 < N) {
                val = *reinterpret_cast<const float4*>(&B[globalK * N + globalCol]);
            } else {
                val.x = (globalK < kEnd && globalCol + 0 < N) ? B[globalK * N + globalCol + 0] : 0.0f;
                val.y = (globalK < kEnd && globalCol + 1 < N) ? B[globalK * N + globalCol + 1] : 0.0f;
                val.z = (globalK < kEnd && globalCol + 2 < N) ? B[globalK * N + globalCol + 2] : 0.0f;
                val.w = (globalK < kEnd && globalCol + 3 < N) ? B[globalK * N + globalCol + 3] : 0.0f;
            }
            Bs[kk][n4 * 4 + 0] = val.x;
            Bs[kk][n4 * 4 + 1] = val.y;
            Bs[kk][n4 * 4 + 2] = val.z;
            Bs[kk][n4 * 4 + 3] = val.w;
        }
        __syncthreads();
        #pragma unroll
        for (int kk = 0; kk < TILE_K; kk++) {
            float a0 = As[ty][kk];
            float a1 = As[ty + THREADS_Y][kk];
            float b0 = Bs[kk][tx];
            float b1 = Bs[kk][tx + THREADS_X];
            sum00 += a0 * b0;
            sum01 += a0 * b1;
            sum10 += a1 * b0;
            sum11 += a1 * b1;
        }
        __syncthreads();
    }
    if (row0 < M && col0 < N) atomicAdd(&C[row0 * N + col0], sum00);
    if (row0 < M && col1 < N) atomicAdd(&C[row0 * N + col1], sum01);
    if (row1 < M && col0 < N) atomicAdd(&C[row1 * N + col0], sum10);
    if (row1 < M && col1 < N) atomicAdd(&C[row1 * N + col1], sum11);
}
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);
    auto C = torch::zeros({M, N}, A.options());
    const int kChunk = 4096;
    int numKBlocks = (K + kChunk - 1) / kChunk;
    dim3 block(THREADS_X, THREADS_Y);
    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M, numKBlocks);
    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K, kChunk
    );
    return C;
}
"""

matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a single matrix multiplication (C = A * B)
    with a large K dimension using a custom CUDA kernel that splits the K
    dimension across the grid's z-dimension and accumulates partial sums
    via atomicAdd.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return matmul_module.matmul_cuda(A.cuda(), B.cuda())


M = 256
N = 256
K = 131072 * 4


def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, N)
    return [A, B]


